True def transform(grid):
    out = [row[:] for row in grid]
    source_row = max(r for r, row in enumerate(grid) if any(row))
    for c, value in enumerate(grid[source_row]):
        if value in (2, 8):
            rise = 4 if value == 2 else 3
            for d in range(1, rise):
                out[source_row - d][c] = 1
            out[source_row - rise][c] = value
    return out
